# A model of a Godot node: a name, one parent, any number of children.
class MiniNode:
	var name := ""
	var parent: MiniNode = null
	var children: Array = []

	func _init(n: String) -> void:
		name = n

	func add_child(child: MiniNode) -> void:
		children.append(child)
		child.parent = self

	func child_named(n: String) -> MiniNode:
		for child in children:
			if child.name == n:
				return child
		return null

	func get_node_or_null(path: String) -> MiniNode:
		var here: MiniNode = self
		for part in path.split("/"):
			if part == "..":
				here = here.parent
			else:
				here = here.child_named(part)
			if here == null:
				return null
		return here

	func tree_lines(depth := 0) -> Array:
		var lines := ["  ".repeat(depth) + name]
		for child in children:
			lines.append_array(child.tree_lines(depth + 1))
		return lines

var root := MiniNode.new("Main")

func _ready() -> void:
	var world := MiniNode.new("World")
	var hud := MiniNode.new("HUD")
	root.add_child(world)
	root.add_child(hud)
	print(root.name, " has ", root.children.size(), " children")
	var player := MiniNode.new("Player")
	world.add_child(player)
	print(root.child_named("HUD").name)
	var sprite := MiniNode.new("Sprite")
	player.add_child(sprite)
	print(root.get_node_or_null("World/Player/Sprite").name)
	print(sprite.get_node_or_null("../../../HUD").name)
	for line in root.tree_lines():
		print(line)

