const SPEED := 80.0       # pixels a second
const RADIUS := 8.0       # the walker is a disc this big, at their feet
const STALL_TIME := 0.25  # seconds of going nowhere before giving up
const CRAWL := 2.0        # px a second: slower than this is going nowhere

var pos := Vector2(40, 60)           # where the walker is
var target := Vector2(280, 150)      # where they are going
var solids: Array[Rect2] = [Rect2(130, 50, 60, 80)]
var walking := true
var arrivals := 0
var stall := 0.0

func _ready() -> void:
	position = Vector2.ZERO           # draw in screen pixels
	arrived.connect(_on_arrived)

func _on_arrived() -> void:
	arrivals += 1
	print("arrived")

## Send the walker somewhere. A click on the view calls this.
func walk_to(p: Vector2) -> void:
	target = p
	walking = true
	stall = 0.0

## How far p is from a rectangle: 0 inside it.
func to_box(p: Vector2, r: Rect2) -> float:
	var nearest := Vector2(clampf(p.x, r.position.x, r.end.x), clampf(p.y, r.position.y, r.end.y))
	return p.distance_to(nearest)

## True when a disc of RADIUS at p overlaps something solid.
func blocked(p: Vector2) -> bool:
	for r in solids:
		if to_box(p, r) < RADIUS:
			return true
	return false

func _process(delta: float) -> void:
	if Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
		walk_to(get_global_mouse_position())
	queue_redraw()
	if not walking:
		return
	var before := pos
	var next := pos.move_toward(target, SPEED * delta)
	if not blocked(Vector2(next.x, pos.y)):
		pos.x = next.x
	if not blocked(Vector2(pos.x, next.y)):
		pos.y = next.y
	if pos.distance_to(before) < CRAWL * delta:
		stall += delta
	else:
		stall = 0.0
	if stall >= STALL_TIME:
		target = pos          # give up: where they stand is where they were going
	if pos == target:
		walking = false
		arrived.emit()

func _draw() -> void:
	draw_rect(Rect2(0, 0, 320, 180), Color("#d9c7a3"))
	for r in solids:
		draw_rect(r, Color("#7a5a45"))
	draw_line(target + Vector2(-4, -4), target + Vector2(4, 4), Color.WHITE, 2.0)
	draw_line(target + Vector2(-4, 4), target + Vector2(4, -4), Color.WHITE, 2.0)
