extends Node2D

const CYCLES := 3.0     # whole waves across the view

var shape := "square"
var volume_db := 0.0
var semitone := 0

func _ready() -> void:
	position = Vector2.ZERO     # draw from the corner of the view

func wave(t: float, kind := "sine") -> float:
	match kind:
		"square":
			return 1.0 if fposmod(t, 1.0) < 0.5 else -1.0
		"triangle":
			return asin(sin(TAU * t)) * (2.0 / PI)
		"saw":
			return fposmod(t, 1.0) * 2.0 - 1.0
		_:
			return sin(TAU * t)

func envelope(x: float) -> float:
	return minf(1.0, x / 0.15) * pow(1.0 - x, 2.2)

func gain(db: float) -> float:
	return pow(10.0, db / 20.0)

func ratio(semitones: int) -> float:
	return pow(2.0, float(semitones) / 12.0)

func _process(delta: float) -> void:
	if Input.is_action_just_pressed("move_left"):
		volume_db = maxf(volume_db - 3.0, -24.0)
		queue_redraw()
	if Input.is_action_just_pressed("move_right"):
		volume_db = minf(volume_db + 3.0, 0.0)
		queue_redraw()
	if Input.is_action_just_pressed("move_up"):
		semitone += 1
		queue_redraw()
	if Input.is_action_just_pressed("move_down"):
		semitone -= 1
		queue_redraw()

func _draw() -> void:
	var last := Vector2(0, 90)
	var cycles := CYCLES * ratio(semitone)
	for x in range(0, 321, 2):
		var env := envelope(x / 320.0)
		var y := 90.0 - wave(x / 320.0 * cycles, shape) * env * gain(volume_db) * 60.0
		var p := Vector2(x, y)
		draw_line(last, p, Color("#f2a65a"), 2)
		last = p
	draw_string(ThemeDB.fallback_font, Vector2(8, 14), "%s  %d dB  %+d semitones" % [shape, int(volume_db), semitone], 0, -1, 12, Color.WHITE)

