func migrate(s: Dictionary) -> Dictionary:
	var v := 1
	if is_number(s.get("version")):
		v = int(s["version"])
	if v < 2:
		if s.has("gold"):
			s["coins"] = s["gold"]
			s.erase("gold")
	return s

func sanitize(s: Dictionary) -> Dictionary:
	var d := default_state()
	if is_number(s.get("coins")):
		d["coins"] = maxi(0, int(s["coins"]))
	if is_number(s.get("day")) and s["day"] >= 1:
		d["day"] = int(s["day"])
	if is_number(s.get("volume")):
		d["volume"] = clampf(s["volume"], 0.0, 1.0)
	if typeof(s.get("name")) == TYPE_STRING and s["name"].strip_edges() != "":
		d["name"] = s["name"].strip_edges().substr(0, 16)
	return d

func from_json(text: String) -> Dictionary:
	var parsed: Variant = JSON.parse_string(text)
	if typeof(parsed) != TYPE_DICTIONARY:
		return default_state()
	return sanitize(migrate(parsed))

func _ready() -> void:
	print(to_json())
	print(from_json("this is not a save"))
	print(from_json('{"coins": 99, "cheat": true}'))
	print(from_json('{"gold": 45, "day": 3, "name": ""}'))

