# The four manners, in the order every question lists its answers.
const DYNAMICS := ["banter", "steady", "bold", "romantic"]
const DAY_LENGTH := 480.0
const FIRST_STEPS := ["step_walk", "step_use", "step_door", "step_meet"]

var picks := {}   # the answer each question got: {"q0": "bold"}
var state := {"name": "You", "mode": "cosy", "dynamic": "steady", "created": false, "first_steps": []}

func pick_answer(step_id: String, key: String) -> void:
	picks[step_id] = key

func tally() -> Dictionary:
	var out := {}
	for step_id in picks.keys():
		var key: String = picks[step_id]
		out[key] = int(out.get(key, 0)) + 1
	return out

func winner() -> String:
	var counts := tally()
	var best := "steady"
	var best_n := 0
	for key in DYNAMICS:
		if int(counts.get(key, 0)) > best_n:
			best_n = int(counts.get(key, 0))
			best = key
	return best

func begin_life(answers: Dictionary, dyn: String) -> void:
	var nm := str(answers.get("name", "")).strip_edges()
	if nm != "":
		state["name"] = nm.substr(0, 16)
	state["mode"] = str(answers.get("mode", "cosy"))
	state["dynamic"] = dyn if DYNAMICS.has(dyn) else "steady"
	state["created"] = true

func mode_price_mult() -> float:
	match state["mode"]:
		"hustle": return 1.3
		"cosy": return 0.9
		_: return 1.0

func mode_event_gap() -> float:
	match state["mode"]:
		"story": return 16.0
		"hustle": return 34.0
		_: return 25.0

func mode_day_scale() -> float:
	match state["mode"]:
		"cosy": return 0.8
		"hustle": return 1.15
		_: return 1.0

func day_seconds() -> float:
	return DAY_LENGTH / mode_day_scale()

func first_step(id: String) -> void:
	var done: Array = state["first_steps"]
	if done.has(id):
		return
	done.append(id)

func first_steps_left() -> Array:
	var out := []
	for id in FIRST_STEPS:
		if not state["first_steps"].has(id):
			out.append(id)
	return out

func _ready() -> void:
	pick_answer("q0", "bold")
	pick_answer("q1", "banter")
	pick_answer("q2", "bold")
	pick_answer("q3", "steady")
	pick_answer("q4", "banter")
	pick_answer("q2", "banter")
	print(tally())
	print("Manner: ", winner())
	begin_life({"name": "  Ada  ", "mode": "cosy"}, winner())
	print(state)
	print("A day lasts ", day_seconds(), " seconds")
	first_step("step_walk")
	first_step("step_walk")
	print(first_steps_left())

