const DAY_LENGTH := 20.0   # seconds; the game's day is 480

var clock_t := 0.0
var night_held := false

func _ready() -> void:
	position = Vector2.ZERO   # draw from the top-left corner of the view

func _process(delta: float) -> void:
	if night_held:
		return
	clock_t += delta
	if clock_t >= DAY_LENGTH:
		clock_t = DAY_LENGTH
		night_held = true

extends Node2D

const DAY_LENGTH := 20.0   # seconds; the game's day is 480

var clock_t := 0.0
var night_held := false

func _ready() -> void:
	position = Vector2.ZERO   # draw from the top-left corner of the view

func _process(delta: float) -> void:
	if night_held:
		return
	clock_t += delta
	if clock_t >= DAY_LENGTH:
		clock_t = DAY_LENGTH
		night_held = true

func day_fraction() -> float:
	return clampf(clock_t / DAY_LENGTH, 0.0, 1.0)

func phase() -> String:
	var f := day_fraction()
	if f < 0.2: return "Morning"
	if f < 0.55: return "Daytime"
	if f < 0.75: return "Evening"
	return "Night"

func clock_text() -> String:
	var mins := int(lerpf(360.0, 1320.0, day_fraction()))
	return "%02d:%02d" % [mins / 60, mins % 60]

extends Node2D

const DAY_LENGTH := 20.0   # seconds; the game's day is 480
const DAWN := Color("#fff4e2")
const NIGHT := Color("#8e98dc")

var clock_t := 0.0
var night_held := false

func _ready() -> void:
	position = Vector2.ZERO   # draw from the top-left corner of the view

func _process(delta: float) -> void:
	queue_redraw()
	if night_held:
		return
	clock_t += delta
	if clock_t >= DAY_LENGTH:
		clock_t = DAY_LENGTH
		night_held = true

func day_fraction() -> float:
	return clampf(clock_t / DAY_LENGTH, 0.0, 1.0)

func phase() -> String:
	var f := day_fraction()
	if f < 0.2: return "Morning"
	if f < 0.55: return "Daytime"
	if f < 0.75: return "Evening"
	return "Night"

func clock_text() -> String:
	var mins := int(lerpf(360.0, 1320.0, day_fraction()))
	return "%02d:%02d" % [mins / 60, mins % 60]

func sky_color() -> Color:
	return DAWN.lerp(NIGHT, day_fraction())

func _draw() -> void:
	draw_rect(Rect2(0, 0, 320, 180), sky_color())
	draw_string(ThemeDB.fallback_font, Vector2(10, 24), clock_text() + "  " + phase(), 0, -1, 16, Color.BLACK)

