	for s in sprites:
		if s["uid"] == uid:
			return s
	return {}

func _process(_delta: float) -> void:
	# The mouse or a finger, turned into the three calls a drag is made of.
	var p := get_global_mouse_position()
	var down := Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT)
	if down and not was_down:
		begin_drag(p)
	elif down:
		drag_to(p)
	elif was_down:
		end_drag()
	was_down = down
	# Space: leave the room and come back. It is made again from the save.
	if Input.is_action_just_pressed("ui_accept"):
		build()
	queue_redraw()

func _draw() -> void:
	draw_rect(Rect2(0, 0, 320, 180), Color("#4a4e69"))
	draw_rect(Rect2(0, 40, 320, 140), Color("#d9c7a8"))
	var order := sprites.duplicate()
	order.sort_custom(func(a, b): return a["z"] < b["z"])
	for s in order:
		draw_rect(s["rect"], CATALOG[s["k"]]["color"])
		if s["uid"] == dragging_uid:
			draw_rect(s["rect"], Color.WHITE, false, 1)

