var day := 1
var romance_style := "one"   # none, one, several or partner
var dynamic := "steady"      # how you carry yourself: banter, bold, romantic or steady
var hearts := {}

func begin_life(style: String, manner: String) -> void:
	day = 1
	hearts = {}
	romance_style = style
	dynamic = manner

func sleep() -> void:
	day += 1

func heart(id: String) -> Dictionary:
	if not hearts.has(id):
		hearts[id] = {"stage": 0, "warmth": 0.0, "last": 0}
