	"kitchen": Rect2(1, 1, 1, 1),
	"living": Rect2(2, 0, 1, 2),
}
const DIR_STEP := {"w": Vector2(-1, 0), "e": Vector2(1, 0), "n": Vector2(0, -1), "s": Vector2(0, 1)}
const DIR_BACK := {"w": "e", "e": "w", "n": "s", "s": "n"}

var here := "bedroom"            # the room you are in
var spot := Vector2(0.5, 0.25)   # where you stand in it: 0 to 1 across, 0 to 1 down

# Which room owns a square of the plan, or "" for none.
func room_at(cell: Vector2) -> String:
	for room in CELLS:
		if CELLS[room].has_point(cell):
			return room
	return ""

# The room on the far side of square i of a wall, or "".
func beyond(room: String, dir: String, i: int) -> String:
	var cells: Rect2 = CELLS[room]
	var step: Vector2 = DIR_STEP[dir]
	var probe: Vector2 = cells.position + (Vector2(i, 0) if step.y != 0 else Vector2(0, i)) + step
	while cells.has_point(probe):
		probe += step
	return room_at(probe)

# Every way out of a room: [{"dir": "e", "room": "kitchen", "from": 0.5, "to": 1.0}, ...]
func exits(room: String) -> Array:
	var out: Array = []
	for dir in DIR_STEP:
		var n := wall_len(room, dir)
		for i in n:
			var other := beyond(room, dir, i)
			if other != "":
				out.append({"dir": dir, "room": other, "from": float(i) / n, "to": float(i + 1) / n})
	return out

