var night_or_rain := false
var caught := 0
var last_fish := ""
var last_cm := 0
var records := {}
var said := "Space to reel it in"

func _ready() -> void:
	position = Vector2.ZERO   # draw from the top-left corner of the view

func _process(delta: float) -> void:
	_t += delta * _speed
	if Input.is_action_just_pressed("ui_accept"):
		reel()
	queue_redraw()

func marker() -> float:
	var f := fposmod(_t, 2.0)
	return f if f <= 1.0 else 2.0 - f

func in_zone() -> bool:
	var m := marker()
	return m >= _zone_start and m <= _zone_start + _zone_size

func zone_rect() -> Rect2:
	return Rect2(TRACK.position.x + TRACK.size.x * _zone_start, TRACK.position.y,
		TRACK.size.x * _zone_size, TRACK.size.y)

func fish_pool(koi_bites: bool) -> Array:
	var pool := ["sardine", "sardine", "sardine", "bass", "bass", "salmon"]
	if koi_bites:
		pool.append("koi")
	return pool

func record_best(key: String, value: float) -> bool:
	var prev := float(records.get(key, 0.0))
	if value > prev:
		records[key] = value
		return true
	return false

func reel() -> void:
	if not in_zone():
		said = "Splash. It got away."
		return
	var pool := fish_pool(night_or_rain)
	last_fish = pool[randi() % pool.size()]
	var info: Dictionary = FISH[last_fish]
	last_cm = randi_range(info["min"], info["max"])
	caught += 1
	said = "A %dcm %s." % [last_cm, str(info["name"]).to_lower()]
	if record_best(last_fish, float(last_cm)):
		said = "A %dcm %s! My biggest yet." % [last_cm, str(info["name"]).to_lower()]

func _draw() -> void:
	draw_rect(Rect2(0, 0, 320, 180), Color("#f3f7f9"))
	draw_rect(TRACK, Color("#dfe9ef"))
	draw_rect(TRACK, Color("#b6c9d4"), false, 2.0)
	draw_rect(zone_rect(), Color(0.49, 0.71, 0.45, 0.55))
	var mx := TRACK.position.x + TRACK.size.x * marker()
	var col := Color("#7fae72") if in_zone() else Color("#e0808f")
	draw_rect(Rect2(mx - 3, TRACK.position.y - 8, 6, TRACK.size.y + 16), col)
	draw_string(ThemeDB.fallback_font, Vector2(20, 40), said, 0, -1, 12, Color("#4c3438"))
	var y := 130.0
	for key in records.keys():
		draw_string(ThemeDB.fallback_font, Vector2(20, y), "best %s: %dcm" % [key, int(records[key])], 0, -1, 10, Color("#8a6b73"))
		y += 13.0

