const SLOTS := 3
const ROOMS := ["bedroom", "kitchen", "beach"]
const CODE_HEADER := "TINYHOME-1"

var disk := {}   # stands in for the phone's storage: path -> the text in the file
var slot := 1
var state := {}

# What FileAccess would do, on the dictionary instead.
func file_exists(path: String) -> bool:
	return disk.has(path)

func read_file(path: String) -> String:
	return disk[path]

func write_file(path: String, text: String) -> void:
	disk[path] = text

func default_state() -> Dictionary:
	return {"day": 1, "coins": 0, "room": "bedroom"}

func slot_path(n: int) -> String:
	return "user://tinyhome_save_slot%d.json" % clampi(n, 1, SLOTS)

func save_now() -> bool:
	write_file(slot_path(slot), JSON.stringify(state))
	return true

func sanitize(s: Dictionary) -> Dictionary:
	var d := default_state()
	if s.has("day") and typeof(s["day"]) in [TYPE_INT, TYPE_FLOAT] and s["day"] >= 1:
		d["day"] = int(s["day"])
	if s.has("coins") and typeof(s["coins"]) in [TYPE_INT, TYPE_FLOAT]:
		d["coins"] = maxi(0, int(s["coins"]))
	if s.has("room") and typeof(s["room"]) == TYPE_STRING and ROOMS.has(s["room"]):
		d["room"] = s["room"]
	return d

func load_save() -> Dictionary:
	if not file_exists(slot_path(slot)):
		return default_state()
	var parsed = JSON.parse_string(read_file(slot_path(slot)))
	if typeof(parsed) != TYPE_DICTIONARY:
		return default_state()
	return sanitize(parsed)

func switch_slot(n: int) -> bool:
	if n < 1 or n > SLOTS or n == slot:
		return false
	save_now()
	slot = n
	state = load_save()
	return true

func backup_code() -> String:
	var json := JSON.stringify(state)
	return "%s:%d:%s" % [CODE_HEADER, json.length(), json]

# The text after the second colon: the life itself.
func code_body(clean: String) -> String:
	var a := clean.find(":")
	var b := clean.find(":", a + 1)
	return clean.substr(b + 1)

func code_problem(text: String) -> String:
	var clean := text.strip_edges()
	if clean == "":
		return "There is nothing pasted in there yet."
	var a := clean.find(":")
	var b := clean.find(":", a + 1)
	if a < 0 or b < 0 or clean.substr(0, a) != CODE_HEADER:
		return "That does not look like a code. It starts with %s." % CODE_HEADER
	var want := int(clean.substr(a + 1, b - a - 1))
	var json := code_body(clean)
	if json.length() != want:
		return "The code is cut short: %d of %d characters arrived." % [json.length(), want]
	if typeof(JSON.parse_string(json)) != TYPE_DICTIONARY:
		return "The code unpacked, but there is no life inside it."
	return ""

func restore_code(text: String) -> bool:
	if code_problem(text) != "":
		return false
	state = sanitize(JSON.parse_string(code_body(text.strip_edges())))
	save_now()
	return true

func earn(amount: int) -> void:
	state["coins"] = int(state["coins"]) + maxi(0, amount)
	save_now()

func _ready() -> void:
	state = default_state()
	earn(30)
	print(read_file(slot_path(slot)))
	state = load_save()
	print(state["coins"])
	switch_slot(2)
	print("slot ", slot, ": ", state["coins"], " coins")
	switch_slot(1)
	print("slot ", slot, ": ", state["coins"], " coins")
	print(backup_code())

