		_finish_line()

func _finish_line() -> void:
	_typing = false
	_hold = 0.0
	_shown = _full.length()

## How long to rest after character i of text, in seconds.
func pause_after(text: String, i: int) -> float:
	var nxt := text[i + 1] if i + 1 < text.length() else " "
	if nxt != " ":
		return 0.0
	var ch := text[i]
	if ch == "." or ch == "!" or ch == "?":
		return PAUSE_STOP
	if ch == "," or ch == ";" or ch == ":":
		return PAUSE_SOFT
	return 0.0

