		return
	if cps() <= 0.0:   # switched to Instant in the middle of a line
		_finish_line()
		return
	if _hold > 0.0:
		_hold = maxf(0.0, _hold - delta)
		if _hold > 0.0:
			return
	var per := 1.0 / cps()
	_budget += delta
	while _budget >= per and _shown < _full.length():
		_budget -= per
		_shown += 1
		var pause := pause_after(_full, _shown - 1)
		if pause > 0.0 and _shown < _full.length():
			_hold = pause
			break
	if _shown >= _full.length():
		_finish_line()

func _process(delta: float) -> void:
	if Input.is_action_just_pressed("ui_up"):
		cycle_text_speed()
	if Input.is_action_just_pressed("ui_accept"):
