extends Node

const DAYS_PER_SEASON := 5
const DAYS_PER_YEAR := DAYS_PER_SEASON * 4
const MEMORY_KEEP := 5      # the game keeps 40
const RECENT := 3           # the game remembers 10 facts
const MAX_PER_ROOM := 2     # the game allows 5
const ARCHIVE_KEEP := 3     # the game keeps 60
const WORDS := ["", "one", "two", "three", "four", "five"]
# room, how many days it lasts, and whether it grows (rather than ages)
const KINDS := {
	"washing_up": {"room": "kitchen", "life": 2, "grows": false, "stages": 1},
	"cards_out": {"room": "living", "life": 3, "grows": false, "stages": 1},
	"confetti": {"room": "living", "life": 4, "grows": false, "stages": 1},
	"flowers": {"room": "living", "life": 6, "grows": false, "stages": 3},
	"laundry": {"room": "bedroom", "life": 8, "grows": true, "stages": 3},
}

var day := 1
var memories := []
var recent := []
var traces := []
var today := {}
var archive := []

# Which year you are in, counting the one you arrived in as the first.
func year() -> int:
	return (maxi(1, day) - 1) / DAYS_PER_YEAR + 1

# Which day of the year it is, 1-based.
func year_day() -> int:
	return (maxi(1, day) - 1) % DAYS_PER_YEAR + 1

# Whole years you have been here.
func years_here() -> int:
	return year() - 1

# "eighteen days", "a year", "two years" - for putting in a sentence.
func years_phrase() -> String:
	var y := years_here()
	if y <= 0:
		return "%d days" % day
	if y == 1:
		return "a year"
	return "%s years" % (WORDS[y] if y < WORDS.size() else str(y))

# Newest first. The same thing twice in one day is one memory.
func log_memory(text: String) -> void:
	for m in memories:
		if m["day"] != day:
			break
		if m["text"] == text:
			return
	memories.insert(0, {"day": day, "text": text})
	while memories.size() > MEMORY_KEEP:
		memories.pop_back()

# Facts the town has remarked on lately, most recent first.
func note_fact(id: String) -> void:
	if recent.has(id):
		recent.erase(id)
	recent.push_front(id)
	while recent.size() > RECENT:
		recent.pop_back()

func traces_in(room: String) -> Array:
	var out := []
	for t in traces:
		if t["room"] == room:
			out.append(t)
	return out

# Leaves one. False for a kind that does not exist.
func leave_trace(id: String) -> bool:
	if not KINDS.has(id):
		return false
	var k: Dictionary = KINDS[id]
	var here := traces_in(k["room"])
	if k["grows"]:
		for t in here:
			if t["kind"] == id:
				t["size"] = mini(t["size"] + 1, k["stages"] - 1)
				t["day"] = day   # still here, so its clock restarts
				return true
	if here.size() >= MAX_PER_ROOM:
		var oldest: Dictionary = here[0]
		for t in here:
			if t["day"] < oldest["day"]:
				oldest = t
		traces.erase(oldest)
	traces.append({"kind": id, "room": k["room"], "day": day, "size": 0})
	return true

# Anything past its life goes without being asked.
func age_traces() -> void:
	var keep := []
	for t in traces:
		if day - t["day"] < KINDS[t["kind"]]["life"]:
			keep.append(t)
	traces = keep

# Which of today's list has been dealt with. Another day's ticks are gone.
func today_done() -> Array:
	if today.get("day", -1) != day:
		return []
	return today["done"]

func tick_today(id: String) -> void:
	if today.get("day", -1) != day:
		today = {"day": day, "done": []}
	if today["done"].has(id):
		return
	today["done"].append(id)

# File a notification instead of losing it. Newest first, once per thing per day.
func archive_notice(id: String, text: String) -> void:
	for row in archive:
		if row["id"] == id and row["day"] == day:
			return
	archive.insert(0, {"day": day, "id": id, "text": text})
	while archive.size() > ARCHIVE_KEEP:
		archive.pop_back()

